// src/lib/rag/context.ts
function buildContext(retrieved) {
  if (!retrieved.length) return "";
  return retrieved.map((r, i) => {
    const c = r.chunk;
    return [
      `[\u0E41\u0E2B\u0E25\u0E48\u0E07\u0E17\u0E35\u0E48 ${i + 1}] ${c.title}`,
      `\u0E2B\u0E21\u0E27\u0E14: ${c.category} | \u0E1B\u0E23\u0E30\u0E40\u0E20\u0E17\u0E0A\u0E34\u0E49\u0E19\u0E02\u0E49\u0E2D\u0E21\u0E39\u0E25: ${c.type}`,
      c.ceremonyId ? `\u0E23\u0E2B\u0E31\u0E2A\u0E1E\u0E34\u0E18\u0E35: ${c.ceremonyId}` : "",
      `\u0E2D\u0E49\u0E32\u0E07\u0E2D\u0E34\u0E07: ${c.source}`,
      c.content
    ].filter(Boolean).join("\n");
  }).join("\n\n---\n\n");
}
function toSources(retrieved) {
  const seen = /* @__PURE__ */ new Set();
  const sources = [];
  for (const r of retrieved) {
    if (seen.has(r.chunk.id)) continue;
    seen.add(r.chunk.id);
    sources.push({
      title: r.chunk.title,
      category: r.chunk.category,
      ceremonyId: r.chunk.ceremonyId,
      chunkId: r.chunk.id,
      type: r.chunk.type
    });
  }
  return sources;
}
